import numpy as np

# MECHANISM: Use an exponential decay function with a log-transformed capacity to give more weight to very large remaining capacities while avoiding worst-fit behavior.
def priority(item, bins):
    max_capacity = 150
    return np.exp((np.log(max_capacity) - np.log(bins)) / 10)

import numpy as np

# MECHANISM: Use a logarithmic decay function with a quadratic scaling factor to give more weight to very large remaining capacities, but with a linear decay factor to avoid worst-fit behavior.
def priority(item, bins):
    max_capacity = 150
    scale_factor = 10
    return max_capacity - scale_factor * np.log1p(bins / max_capacity)

import numpy as np

# MECHANISM: Use a multiplicative factor based on the remaining capacity and a logarithmic decay to avoid worst-fit behavior.

def priority(item, bins):
    max_capacity = 150
    decay_factor = 0.5
    return (max_capacity - bins) / max_capacity * np.exp(-(bins - item) * decay_factor)
